CREATE OR REPLACE FUNCTION public.public_piece_favorite_counts() RETURNS TABLE(piece_id text,favorite_count bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,count(f.piece) FROM public.pieces p JOIN public.rooms r ON r.id=p.artist AND r.published LEFT JOIN public.favorites f ON f.piece=p.id WHERE p.status<>'hidden' GROUP BY p.id UNION ALL SELECT s.id,count(f.piece) FROM (VALUES ('p13'::text),('p14'::text)) s(id) LEFT JOIN public.favorites f ON f.piece=s.id GROUP BY s.id $$;